struct OrderMessage { std::string id; std::string customer_id; long long total_minor; };

OrderMessage to_message(const Order& o) {            // structural half, one TU
    return {o.id(), o.customer().id(), o.total().minor_units()};
}
void to_json(nlohmann::json& j, const OrderMessage& m) {
    j = {{"id", m.id}, {"customer_id", m.customer_id}, {"total_minor", m.total_minor}};
}
void from_json(const nlohmann::json& j, OrderMessage& m) {
    j.at("id").get_to(m.id); j.at("customer_id").get_to(m.customer_id); j.at("total_minor").get_to(m.total_minor);
}

